/* Parent-first diagnostic application. Learning routes are not part of this flow. */
state.diagnosticReports??=[];state.voicePreference??='browser:auto';state.voiceEffects??=true;
let voiceBank=globalThis.ORBITA_VOICE_BANK||{status:'not_connected',profiles:[{id:'orbi',name:'Орби',description:'Тёплый мультяшный проводник',ready:false,clips:{}},{id:'luna',name:'Луна',description:'Мягкий сказочный голос',ready:false,clips:{}},{id:'spark',name:'Искра',description:'Бодрый маленький герой',ready:false,clips:{}}]};
if(!globalThis.ORBITA_EMBEDDED_ASSETS&&location.protocol!=='file:')fetch('voice-bank.json',{cache:'no-cache'}).then(r=>r.ok?r.json():null).then(data=>{if(data?.profiles)voiceBank=data;if(view==='settings')renderParentSettings();}).catch(()=>{});
function selectedNeural(){return voiceBank.profiles.find(p=>p.id===state.voicePreference&&p.ready);}
function browserVoice(){const list=window.speechSynthesis?.getVoices()||[];const id=state.voicePreference.startsWith('browser:')?state.voicePreference.slice(8):'auto';return list.find(v=>v.voiceURI===id)||list.find(v=>v.lang==='en-US')||list.find(v=>/^en/.test(v.lang));}
function browserToken(text,token){return new Promise(resolve=>{if(!window.speechSynthesis||token!==gameCueToken){resolve(false);return;}const u=new SpeechSynthesisUtterance(text),voice=browserVoice();if(voice)u.voice=voice;u.lang='en-US';u.rate=.85;u.pitch=1;let ended=false;const finish=ok=>{if(ended)return;ended=true;clearTimeout(timer);gameWaiters.delete(finish);resolve(ok&&token===gameCueToken);};const timer=setTimeout(()=>finish(false),7000);gameWaiters.add(finish);u.onend=()=>finish(true);u.onerror=()=>finish(false);try{speechSynthesis.speak(u);}catch{finish(false);}});}
async function voiceToken(kind,value,token){const p=selectedNeural();if(p){const url=p.clips?.[kind+':'+value];if(!url)return false;return gameClip(url,token);}return browserToken(kind==='letter'?DiagnosisCore.names[value]:value,token);}
playFeedback=function(correct){if(!state.voiceEffects)return;const variant=gameDeck.next(correct);gameEffectAudio?.pause();gameEffectAudio=new Audio(`assets/effects/${correct?'correct':'wrong'}-${variant}.wav`);gameEffectAudio.volume=.8;gameEffectAudio.play().catch(()=>{});return variant;};
showDiagnosticIntro=function(){showModal(`<div class="diagnosis-intro"><h2>Проверка букв и звуков</h2><p>52 коротких задания. Названия и звуки проверяются отдельно, небольшими блоками.</p><p>Ребёнок выбирает ответы самостоятельно. Не подсказывайте во время проверки.</p><p class="scope-note">Проверяем узнавание на слух. Самостоятельное произношение и чтение текста эта проверка не оценивает.</p><button class="primary" onclick="modal.close();startDiagnostic()">Начать диагностику</button></div>`);};
startDiagnostic=function(){clearTimeout(diagnosticTimer);cancelGameCue();unlockGameAudio();quiz=DiagnosisCore.create();state.pendingQuiz=quiz;persist();renderDiagnostic();};
const drawGameField=renderDiagnostic;
renderDiagnostic=function(){if(quiz?.schemaVersion!==5){showDiagnosticIntro();return;}quiz.schemaVersion=4;drawGameField();quiz.schemaVersion=5;state.pendingQuiz=quiz;persist();document.body.classList.add('diagnostic-child');document.getElementById('crumb').textContent='Диагностика';const toolbar=document.querySelector('.adventure-toolbar');if(toolbar)toolbar.innerHTML=`<button class="secondary" onclick="exitQuiz()">Ⅱ Пауза</button><span>${quiz.items[quiz.index].mode==='name'?'Название':'Звук'} · ${quiz.index+1} / ${quiz.items.length}</span>`;const q=quiz.items[quiz.index];const heading=document.querySelector('.game-heading');if(heading)heading.innerHTML=`<h1>${q.task==='audio'?'Какой звук у буквы?':q.task==='picture'?'Выбери картинку':q.task==='word'?'С какого звука слово?':'Выбери букву'}</h1>`;document.querySelector('.buddy-speech')?.remove();document.querySelector('.buddy-name')?.remove();document.querySelector('.game-reaction')?.remove();const progress=document.querySelector('.adventure-progress');if(progress){const c=DiagnosisCore.coverage(quiz);progress.innerHTML=`<div class="diagnostic-counters"><span>Названия <b>${c.names}/26</b></span><span>Звуки <b>${c.sounds}/26</b></span><div class="diagnostic-line"><i style="width:${quiz.index/52*100}%"></i></div></div>`;}document.querySelectorAll('.sound-adventure>.reward-collection').forEach(e=>e.remove());const bar=document.querySelector('.game-audio-bar');if(bar)bar.innerHTML='<button class="game-replay" onclick="autoGameCue()" aria-label="Повторить озвучку">♫</button><span id="cueStatus" role="status"></span>';};
autoGameCue=async function(){cancelGameCue();unlockGameAudio();const q=quiz?.items[quiz.index];if(!q||view!=='assessment')return;const token=gameCueToken,run=quiz;heardQuestion=null;const status=document.getElementById('cueStatus');if(status){status.textContent='Слушай';status.setAttribute('aria-busy','true');}const notice=document.getElementById('autoAudioNotice');if(notice)notice.hidden=true;let ok=true;
 if(q.task==='audio'){for(let i=0;i<q.options.length;i++){if(token!==gameCueToken)return;document.querySelectorAll('.audio-option').forEach(e=>e.classList.toggle('is-listening',Number(e.dataset.option)===i));if(status)status.textContent=String(i+1);const played=await gameClip('assets/phonemes/'+q.options[i]+'.mp3',token);ok=ok&&played;if(played)markOptionHeard(q,i);if(!await gamePause(280,token))return;}document.querySelectorAll('.audio-option').forEach(e=>e.classList.remove('is-listening'));}
 else{const cues=DiagnosisCore.cuePlan(q);for(let repeat=0;repeat<cues.length;repeat++){if(token!==gameCueToken)return;const cue=cues[repeat];if(cue.kind==='phoneme')ok=await gameClip('assets/phonemes/'+cue.value+'.mp3',token)&&ok;else ok=await voiceToken(cue.kind,cue.value,token)&&ok;if(repeat<cues.length-1&&!await gamePause(320,token))return;}}
 if(token!==gameCueToken||quiz!==run)return;if(ok){heardQuestion=GameCore.key(q);quiz.cueEndedAt=Date.now();quiz.replays??={};quiz.replays[heardQuestion]=(quiz.replays[heardQuestion]||0)+1;state.pendingQuiz=quiz;persist();if(status){status.textContent='';status.setAttribute('aria-busy','false');}}else{if(status)status.textContent='';audioBlocked();}};
listenPictureWord=async function(l){const was=heardQuestion;cancelGameCue();await voiceToken('word',GameCore.pictures[l].word,gameCueToken);heardQuestion=was;};
const scoreDiagnosticAnswer=answerDiagnostic;
answerDiagnostic=function(answer,button){if(quiz?.schemaVersion!==5)return;const before=quiz.answers.length;scoreDiagnosticAnswer(answer,button);if(quiz.answers.length>before){const last=quiz.answers.at(-1);if(last.attempt===1){last.responseMs=Date.now()-(quiz.cueEndedAt||quiz.questionOpenedAt||Date.now());persist();}document.getElementById('gameReaction')?.remove();const status=document.getElementById('cueStatus');if(status)status.textContent='';}};
const diagnoseOpen=renderDiagnostic;
renderDiagnostic=function(){diagnoseOpen();if(quiz?.schemaVersion===5)quiz.questionOpenedAt=Date.now();};
gameSpeak=()=>Promise.resolve(true);
audioBlocked=function(){const node=document.getElementById('autoAudioNotice');if(node){node.hidden=false;node.innerHTML='<button class="primary" onclick="unlockGameAudio();autoGameCue()">Включить озвучку</button>';}};
const quietReward=showReward;
showReward=function(award,next){quietReward(award,next);window.speechSynthesis?.cancel();const note=document.querySelector('.reward-celebration>small');if(note)note.remove();};
function renderParentHome(){document.body.classList.remove('diagnostic-child');const d=state.diagnostic;app.innerHTML=`<div class="parent-heading"><span class="eyebrow">ДЛЯ РОДИТЕЛЕЙ</span><h1>Диагностика чтения</h1><p>Узнайте, какие названия и звуки английских букв ребёнок узнаёт самостоятельно.</p></div><section class="diagnosis-start"><div><h2>Буквы и звуки</h2><p>52 задания · около 7–10 минут</p><div class="scope-tags"><span>26 названий</span><span>26 звуков</span><span>4 формата заданий</span></div><label class="field">Имя ребёнка<input id="diagnosisChildName" value="${escapeHTML(state.name)}" maxlength="40" autocomplete="off"></label><div class="controls"><button class="primary" onclick="beginParentDiagnostic()">${state.pendingQuiz?.schemaVersion===5?'Продолжить диагностику':'Начать диагностику'}</button>${d?.detail?'<button class="secondary" onclick="navigate(\'results\')">Последний отчёт</button>':''}</div></div><img src="assets/orbit-world.png" alt="Орби с книгой"></section><div class="scope-note">Проверяем узнавание названий и звуков букв. Чтение слов, текста и произношение в эту проверку не входят.</div>`;}
function beginParentDiagnostic(){const field=document.getElementById('diagnosisChildName');if(field?.value.trim())state.name=field.value.trim();persist();if(state.pendingQuiz?.schemaVersion===5)continueLearning();else showDiagnosticIntro();}
function statusText(skill){return !skill.completed?'Не проверено':skill.firstTry?'Верно сразу':'Были ошибки';}
function reportCard(d){const troubleNames=d.detail.filter(x=>x.name.errors.length).map(x=>x.letter.toUpperCase()),troubleSounds=d.detail.filter(x=>x.sound.errors.length).map(x=>x.letter.toUpperCase());return `<section class="parent-report"><div class="report-title"><div><span class="eyebrow">ОТЧЁТ ПО ДИАГНОСТИКЕ</span><h1>${escapeHTML(d.childName||state.name)}</h1><p>${new Date(d.at).toLocaleString('ru-RU')}</p></div><div class="controls"><button class="secondary" onclick="exportDiagnosticReport()">Скачать данные</button><button class="secondary" onclick="window.print()">Печать</button></div></div><div class="parent-score-grid"><div><span>Названия букв</span><strong>${d.names}<small>/26</small></strong><p>Верно с первой попытки</p></div><div><span>Звуки букв</span><strong>${d.sounds}<small>/26</small></strong><p>Верно с первой попытки</p></div></div><div class="report-findings"><h2>Где возникли затруднения</h2><p><b>Названия:</b> ${troubleNames.join(', ')||'ошибок не зафиксировано'}.</p><p><b>Звуки:</b> ${troubleSounds.join(', ')||'ошибок не зафиксировано'}.</p></div><div class="scope-note">Результат относится к узнаванию названий и базовых звуков букв. Чтение слов и текста, понимание и самостоятельное произношение не оценивались. Исправленный ответ не заменяет результат первой попытки.</div><h2>По каждой букве</h2><div class="report-table-scroll"><table class="diagnostic-table"><thead><tr><th>Буква</th><th>Название</th><th>Звук</th><th>Ошибочные ответы</th></tr></thead><tbody>${d.detail.map(x=>`<tr><th>${x.letter.toUpperCase()} <span>${x.letter}</span></th><td class="${x.name.errors.length?'needs-review':'verified'}">${statusText(x.name)}</td><td class="${x.sound.errors.length?'needs-review':'verified'}">${statusText(x.sound)}</td><td>${x.name.errors.length?'Название: '+x.name.errors.map(e=>e.answer.toUpperCase()).join(' → '):''}${x.name.errors.length&&x.sound.errors.length?'<br>':''}${x.sound.errors.length?'Звук: '+x.sound.errors.map(e=>e.answer.toUpperCase()).join(' → '):''}${!x.name.errors.length&&!x.sound.errors.length?'—':''}</td></tr>`).join('')}</tbody></table></div><details class="parent-details"><summary>Форматы заданий и ответы</summary>${renderEvidence(d)}</details><div class="report-actions"><button class="primary" onclick="showDiagnosticIntro()">Новая диагностика</button><button class="secondary" onclick="navigate('home')">В кабинет</button></div></section>`;}
function renderEvidence(d){const source=d.taskEvidence||d.answers||[];const labels={name:'Узнать название',letter:'Звук → буква',picture:'Звук → картинка',word:'Первый звук слова',audio:'Буква → звук'};return `<div class="evidence-list">${source.map(e=>`<div><b>${e.letter.toUpperCase()} · ${e.mode==='name'?'название':'звук'}</b><span>${labels[e.task]||labels[e.mode]||e.mode}</span><span>Выбран ${e.answer.toUpperCase()} · попытка ${e.attempt||1} · ${e.correct?'верно':'ошибка'}</span></div>`).join('')}</div>`;}
function renderParentReports(){document.body.classList.remove('diagnostic-child');const d=state.diagnostic;if(d?.detail){app.innerHTML=reportCard(d);return;}app.innerHTML='<div class="empty"><h1>Отчётов пока нет</h1><p>После диагностики здесь появятся отдельные результаты по названиям и звукам.</p><button class="primary" onclick="navigate(\'home\')">Начать диагностику</button></div>';}
function exportDiagnosticReport(){const d=state.diagnostic;if(!d)return;const blob=new Blob([JSON.stringify(d,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='diagnostic-report-'+new Date(d.at).toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
finishDiagnostic=function(){clearTimeout(diagnosticTimer);cancelGameCue();const d=DiagnosisCore.report(quiz,state.name);if(!d.completed){renderDiagnostic();return;}state.diagnostic=d;state.diagnosticReports.push(d);state.sessions.push({type:'diagnostic',at:d.at,names:d.names,sounds:d.sounds,details:d.detail});delete state.pendingQuiz;persist();navigate('results');};
continueLearning=function(){if(state.pendingQuiz?.schemaVersion===5){quiz=state.pendingQuiz;while(quiz.index<quiz.items.length&&GameCore.events(quiz,quiz.items[quiz.index]).some(e=>e.correct))quiz.index++;unlockGameAudio();if(quiz.index>=quiz.items.length)finishDiagnostic();else renderDiagnostic();return;}showDiagnosticIntro();};
function renderParentSettings(){document.body.classList.remove('diagnostic-child');const voices=(window.speechSynthesis?.getVoices()||[]).filter(v=>/^en/.test(v.lang));app.innerHTML=`<div class="parent-heading"><h1>Настройки</h1><p>Голос озвучки применяется ко всем названиям букв и словам.</p></div><section class="settings-card"><h2>Мультяшные нейроголоса</h2><p class="voice-state">${voiceBank.profiles.some(p=>p.ready)?'Доступные голоса':'Нейроозвучка подготовлена к подключению. Голоса пока не активированы.'}</p><div class="neural-voice-grid">${voiceBank.profiles.map(p=>`<article class="neural-voice-card"><span class="voice-character">${p.id==='orbi'?'✦':p.id==='luna'?'☾':'✧'}</span><h3>${escapeHTML(p.name)}</h3><p>${escapeHTML(p.description)}</p><button class="${p.ready?'primary':'secondary'}" ${p.ready?'':'disabled'} onclick="setDiagnosticVoice('${p.id}')">${p.ready?(state.voicePreference===p.id?'Выбран':'Выбрать'):'Ещё не подключён'}</button></article>`).join('')}</div><p class="settings-note">Нейроголоса создаются ИИ. Учебные фонемы воспроизводятся из отдельного эталонного набора.</p></section><section class="settings-card"><h2>Временная озвучка</h2><p>До подключения нейроголосов используется доступный английский голос браузера.</p><label class="field">Голос<select id="browserVoiceSelect" onchange="setDiagnosticVoice(this.value)"><option value="browser:auto">Автоматически</option>${voices.map(v=>`<option value="browser:${escapeHTML(v.voiceURI)}" ${state.voicePreference==='browser:'+v.voiceURI?'selected':''}>${escapeHTML(v.name)}</option>`).join('')}</select></label><label class="toggle-field"><input type="checkbox" ${state.voiceEffects?'checked':''} onchange="state.voiceEffects=this.checked;persist()"> Звуковые реакции на ответ</label><details class="parent-details"><summary>Об озвучке</summary><p>Записи фонем: <a href="https://phonicademy.com" target="_blank" rel="noopener">Phonicademy</a>, <a href="https://phonicademy.com/audio-license" target="_blank" rel="noopener">лицензия</a>.</p></details></section>`;}
function setDiagnosticVoice(id){if(!id.startsWith('browser:')&&!voiceBank.profiles.some(p=>p.id===id&&p.ready))return;state.voicePreference=id;persist();renderParentSettings();}
exitQuiz=function(){clearTimeout(diagnosticTimer);cancelGameCue();state.pendingQuiz=quiz;persist();showModal('<h2>Проверка приостановлена</h2><p>Ответы сохранены на этом устройстве.</p><div class="controls"><button class="primary" onclick="modal.close();navigate(\'home\')">В кабинет</button><button class="secondary" onclick="modal.close();renderDiagnostic()">Продолжить</button></div>');};
showAudioSettings=function(){navigate('settings');};
navigate=function(next){cancelGameCue();clearTimeout(diagnosticTimer);document.body.classList.remove('diagnostic-child');view=next;const labels={home:'Диагностика',results:'Отчёты',settings:'Настройки'};document.getElementById('crumb').textContent=labels[next]||labels.home;document.getElementById('nav').innerHTML=[['home','route','Диагностика'],['results','chart','Отчёты'],['settings','star','Настройки']].map(([id,ic,label])=>`<button class="${next===id?'active':''}" onclick="navigate('${id}')">${icon(ic)}${label}</button>`).join('');if(next==='results')renderParentReports();else if(next==='settings')renderParentSettings();else renderParentHome();window.scrollTo(0,0);};
if(state.pendingQuiz&&state.pendingQuiz.schemaVersion!==5){state.archivedPendingQuiz=state.pendingQuiz;delete state.pendingQuiz;persist();}
document.querySelector('.parent')?.remove();const footer=document.querySelector('footer');if(footer)footer.innerHTML='<span>Орбита · диагностика букв и звуков</span><button class="text-btn" onclick="showSchool()">Связаться со школой ↗</button>';const asideBottom=document.querySelector('.aside-bottom');if(asideBottom)asideBottom.innerHTML='<span class="sidebar-note">Личный кабинет родителя</span>';const theme=document.querySelector('.theme-btn');if(theme){theme.textContent='Настройки';theme.onclick=()=>navigate('settings');}
document.querySelector('.brand').onclick=e=>{e.preventDefault();navigate('home');};
navigate('home');
